/// Gate 14C: Replication Contract Test
///
/// CRITICAL: Before scaling measurement, prove the replication harness is correct.
///
/// This test validates that ReplicationMessages are delivered through the real path:
///   operation → replication_message → receiver → deduplication → causal_validation → apply → state
///
/// Contract: leader.state_hash == replica.state_hash after all operations applied
///
/// Test cases:
/// 1. Basic: N operations delivered in order → convergence ✓
/// 2. Duplicate: Same message delivered twice → deduplication prevents double-apply
/// 3. Reordered: Messages delivered out of order → causal validation preserves order
/// 4. Delayed: Messages arrive late → eventual convergence ✓
/// 5. Dropped + Retx: Message lost then resent → reconciliation recovers it
/// 6. Causal dependency: Operation depends on prior → waiting/ready state correct
use feltdb::{
    convergence::VectorClock,
    distributed_transactions::{DistributedTransactionExecutor, ReplicationMessage},
    state_hash::StateHash,
    transactions::{ConsistencyContract, Operation, OperationCommand, OperationId, StateVersion},
};
use std::collections::HashMap;

// ============================================================================
// REPLICATION HARNESS
// ============================================================================

/// Simulates network delivery with configurable behavior (drops, delays, reordering)
#[allow(dead_code)]
struct ReplicationTransport {
    messages: Vec<(usize, ReplicationMessage)>, // (destination_replica_id, message)
    #[allow(dead_code)]
    drops_enabled: bool,
    #[allow(dead_code)]
    delays_enabled: bool,
    #[allow(dead_code)]
    reordering_enabled: bool,
}

#[allow(dead_code)]
impl ReplicationTransport {
    fn new() -> Self {
        Self {
            messages: Vec::new(),
            drops_enabled: false,
            delays_enabled: false,
            reordering_enabled: false,
        }
    }

    fn send(&mut self, replica_id: usize, msg: ReplicationMessage) {
        self.messages.push((replica_id, msg));
    }

    fn deliver_all(&mut self) -> Vec<(usize, ReplicationMessage)> {
        self.messages.drain(..).collect()
    }

    fn deliver_with_drops(&mut self, drop_every_nth: usize) -> Vec<(usize, ReplicationMessage)> {
        let mut delivered = Vec::new();
        for (i, msg) in self.messages.drain(..).enumerate() {
            if i % drop_every_nth != 0 {
                delivered.push(msg);
            }
        }
        delivered
    }
}

